class TrayIcon:
    """System tray icon with Show and Exit menu items."""

    def __init__(
        self,
        on_show: Callable[[], None],
        on_exit: Callable[[], None],
    ) -> None:
        self.on_show = on_show
        self.on_exit = on_exit
        self.icon: pystray.Icon | None = None
        self._thread: threading.Thread | None = None

    def _create_image(self) -> Image.Image:
        for name in ("icon.png", "icon.ico"):
            icon_path = Path(__file__).with_name("assets") / name
            if icon_path.exists():
                try:
                    return Image.open(icon_path)
                except Exception:
                    pass
        width = 64
        height = 64
        image = Image.new("RGB", (width, height), "white")
        dc = ImageDraw.Draw(image)
        dc.rectangle([0, 0, width, height], fill="#e44332")
        dc.text((width // 2 - 10, height // 2 - 14), "T", fill="white")
        return image

    def _setup_menu(self) -> pystray.Menu:
        return pystray.Menu(
            pystray.MenuItem("Показать окно", self._show),
            pystray.MenuItem("Выход", self._exit),
        )

    def _show(self, _icon: pystray.Icon) -> None:
        self.on_show()

    def _exit(self, _icon: pystray.Icon) -> None:
        self.on_exit()
        if self.icon is not None:
            self.icon.stop()

    def _run(self) -> None:
        self.icon = pystray.Icon(
            "task_reminder",
            self._create_image(),
            "Task Reminder",
            menu=self._setup_menu(),
        )
        self.icon.run()

    def start(self) -> None:
        if self._thread is not None and self._thread.is_alive():
            return
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        if self.icon is not None:
            self.icon.stop()
        if self._thread is not None:
            self._thread.join(timeout=2)

